"""
Speech Domain Models

Deterministic local speech assets (mock provider output).

Author: eKlAVYA Backend
Version: 1.0.0
"""

from datetime import datetime
from typing import Dict, Literal, Optional

from pydantic import BaseModel, Field

from models.common import Entity

MOCK_SPEECH_DISCLAIMER = (
    "Mock asset: silent placeholder generated by the local development "
    "provider. This is not synthesized speech."
)


class SpeechAsset(Entity):
    __collection__ = "speech_assets"

    owner_id: str
    source_type: str  # note | scan | message | transcript
    source_id: Optional[str] = None
    transcript: str
    language: str = "en"
    voice_settings: Dict = Field(default_factory=dict)
    content_hash: str

    media_storage_name: str
    media_content_type: str = "audio/wav"
    duration_seconds: Optional[int] = None

    is_mock: bool = True
    mock_disclaimer: str = MOCK_SPEECH_DISCLAIMER


# ---------------------------------------------------------------------------
# API schemas
# ---------------------------------------------------------------------------

SpeechSourceType = Literal["note", "scan", "transcript"]


class SpeechCreate(BaseModel):
    """Request body for POST /speech."""

    source_type: SpeechSourceType
    source_id: Optional[str] = None
    transcript: str = Field(min_length=1)
    language: str = "en"
    voice_settings: Dict = Field(default_factory=dict)


class SpeechAssetOut(BaseModel):
    """Speech asset representation returned by the API."""

    id: str
    owner_id: str
    source_type: str
    source_id: Optional[str] = None
    transcript: str
    language: str
    voice_settings: Dict
    content_hash: str
    media_content_type: str
    duration_seconds: Optional[int] = None
    is_mock: bool
    mock_disclaimer: str
    media_available: bool
    created_at: datetime
    cached: bool = False


class PlaybackUrlOut(BaseModel):
    """Authorized local playback route for a speech asset."""

    asset_id: str
    url: str
    authorization: str
    expires_at: datetime
    is_mock: bool
    disclaimer: str
    media_available: bool
